import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { createHash, X509Certificate } from 'node:crypto';
import { existsSync } from 'node:fs';
import { mkdtemp, readFile, rm } from 'node:fs/promises';
import { createServer } from 'node:https';
import { createRuntime, ORIGIN } from '../../tizen-ci-triage/scripts/ci_triage/qb_browser_agent.mjs';

// Fact-finding probe: preserve the production dual-stage guard and compare both
// browser body APIs with newly generated bytes actually sent by local HTTPS.
const [playwright, chromium] = process.argv.slice(2);
assert.ok(playwright && chromium, 'pass the Playwright module and Chromium executable paths');
const prefix = Buffer.from('<!doctype html><link rel="icon" href="data:,"><p>');
const suffix = Buffer.from('</p>');
const vectors = [
  { name: 'latin1-cafe', charset: 'ISO-8859-1', payload: Buffer.from('caf\u00e9', 'latin1') },
  { name: 'invalid-utf8', charset: 'UTF-8', payload: Buffer.from([0xc3, 0x28]) },
  { name: 'valid-utf8-cafe', charset: 'UTF-8', payload: Buffer.from('caf\u00e9') },
  { name: 'valid-utf8-literal-replacement', charset: 'UTF-8', payload: Buffer.from('\ufffd') },
].map((vector, index) => ({ ...vector, path: `/build/${901 + index}`,
  contentType: `text/html; charset=${vector.charset}`,
  body: Buffer.concat([prefix, vector.payload, suffix]) }));
const routes = new Map(vectors.map(vector => [vector.path, vector]));
const received = [];
const rows = [];
const emit = value => console.log(JSON.stringify(value));
const hash = bytes => createHash('sha256').update(bytes).digest('hex');
const shellQuote = value => `'${value.replaceAll("'", "'\\''")}'`;
emit({ type: 'invocation', timestamp: new Date().toISOString(), cwd: process.cwd(),
  command: ['env', 'ELECTRON_RUN_AS_NODE=1', process.execPath, ...process.argv.slice(1)]
    .map(shellQuote).join(' '),
  node: process.version,
  probe_sha256: hash(await readFile(new URL(import.meta.url))),
  production_sha256: hash(await readFile(new URL('../../tizen-ci-triage/scripts/ci_triage/qb_browser_agent.mjs', import.meta.url))),
  network: 'synthetic loopback HTTPS only', guard: 'production browser-root Fetch Request + Response stages' });

function describeBody(bytes, vector) {
  const payload = bytes.subarray(prefix.length, bytes.length - suffix.length);
  let strictDecode;
  try { strictDecode = { ok: true, text: new TextDecoder(vector.charset, { fatal: true }).decode(payload) }; }
  catch (error) { strictDecode = { ok: false, error: error.name }; }
  return { hex: bytes.toString('hex'), payload_hex: payload.toString('hex'),
    byte_length: bytes.length, matches_server: bytes.equals(vector.body), strict_decode: strictDecode };
}

const directory = await mkdtemp('/dev/shm/p5q-c2c-raw-bytes-');
let server;
let runtime;
let restore;
try {
  execFileSync('openssl', ['req', '-x509', '-newkey', 'rsa:2048', '-nodes',
    '-keyout', `${directory}/key.pem`, '-out', `${directory}/cert.pem`, '-days', '1',
    '-subj', '/CN=quickbuild.tizen.org', '-addext', 'subjectAltName=DNS:quickbuild.tizen.org'],
  { stdio: 'ignore' });
  const cert = await readFile(`${directory}/cert.pem`);
  const key = await readFile(`${directory}/key.pem`);
  const spki = createHash('sha256').update(new X509Certificate(cert).publicKey.export({
    type: 'spki', format: 'der',
  })).digest('base64');
  server = createServer({ cert, key }, (request, response) => {
    const vector = routes.get(request.url);
    received.push({ method: request.method, path: request.url, host: request.headers.host,
      remote: request.socket.remoteAddress, body_hex_sent: vector?.body.toString('hex') ?? null });
    request.resume();
    response.writeHead(vector ? 200 : 404, { 'Content-Type': vector?.contentType ?? 'text/plain',
      'Cache-Control': 'no-store', 'Content-Length': vector?.body.length ?? 0 });
    response.end(vector?.body);
  });
  await new Promise((resolve, reject) => {
    server.once('error', reject);
    server.listen(0, '127.0.0.1', resolve);
  });
  runtime = await createRuntime(playwright, chromium, { launchArgs: ['--no-proxy-server',
    `--host-resolver-rules=MAP quickbuild.tizen.org 127.0.0.1:${server.address().port}, EXCLUDE 127.0.0.1, MAP * ~NOTFOUND`,
    `--ignore-certificate-errors-spki-list=${spki}`] });
  emit({ type: 'runtime', chromium: runtime.browser.version(),
    startup_trace: runtime.trace, local_port: server.address().port });

  const root = runtime.guards.root;
  const originalSend = root.send;
  const send = originalSend.bind(root);
  const paused = new Map();
  const observePause = event => {
    const url = new URL(event.request.url);
    const vector = url.origin === ORIGIN && routes.get(url.pathname + url.search);
    if (!vector) return;
    let record = paused.get(event.requestId);
    if (!record) {
      record = { vector, requestId: event.requestId, order: [], responseStatus: null };
      paused.set(event.requestId, record);
    }
    const response = event.responseStatusCode !== undefined;
    record.order.push(response ? 'response-paused' : 'request-paused');
    if (response) record.responseStatus = event.responseStatusCode;
  };
  // Observe metadata before the existing production handler calls root.send.
  root.prependListener('Fetch.requestPaused', observePause);
  root.send = async (method, params) => {
    const record = paused.get(params?.requestId);
    if (record && method === 'Fetch.continueRequest') record.order.push('continue-request');
    if (!record || method !== 'Fetch.continueResponse') return send(method, params);
    record.order.push('get-response-body');
    try {
      const result = await send('Fetch.getResponseBody', { requestId: params.requestId });
      const bytes = Buffer.from(result.body, result.base64Encoded ? 'base64' : 'utf8');
      record.fetch = { base64_encoded: result.base64Encoded, ...describeBody(bytes, record.vector) };
      record.order.push('get-response-body-complete');
    } catch (error) {
      record.fetch = { error: error.message };
      record.order.push('get-response-body-failed');
    }
    // Even a failed probe does not change the guard's original allow/deny action.
    record.order.push('continue-response');
    return send(method, params);
  };
  restore = () => { root.send = originalSend; root.removeListener('Fetch.requestPaused', observePause); };

  runtime.policy.phase = 'read';
  for (const vector of vectors) {
    const response = await runtime.page.goto(ORIGIN + vector.path, { waitUntil: 'load', timeout: 15000 });
    assert.equal(response.status(), 200);
    assert.equal(await response.headerValue('content-type'), vector.contentType);
    assert.equal(response.request().redirectedFrom(), null);
    const records = [...paused.values()].filter(record => record.vector === vector);
    assert.equal(records.length, 1, 'expected one guarded navigation per vector');
    const record = records[0];
    record.order.push('playwright-body');
    // A separate, direct Page navigation uses the unchanged Playwright response API.
    const body = await response.body();
    record.order.push('playwright-body-complete');
    const row = { type: 'body-comparison', name: vector.name, path: vector.path,
      content_type: vector.contentType, response_status: record.responseStatus,
      request_id: record.requestId, expected: describeBody(vector.body, vector),
      fetch: record.fetch, playwright: describeBody(body, vector), order: record.order };
    rows.push(row);
    emit(row);
    assert.equal(record.responseStatus, 200);
    assert.deepEqual(record.order, ['request-paused', 'continue-request', 'response-paused',
      'get-response-body', record.fetch.error ? 'get-response-body-failed' : 'get-response-body-complete',
      'continue-response', 'playwright-body', 'playwright-body-complete']);
  }
  assert.equal(runtime.failure, null);
  assert.deepEqual(received.map(request => request.path), vectors.map(vector => vector.path));
  for (const request of received) {
    assert.equal(request.remote, '127.0.0.1');
    assert.equal(request.host, 'quickbuild.tizen.org');
    assert.equal(request.method, 'GET');
  }
  const fetchPreserves = rows.every(row => row.fetch.matches_server === true);
  emit({ type: 'summary', vectors: rows.length, requests: received,
    fetch_preserves_every_body: fetchPreserves,
    playwright_preserves_every_body: rows.every(row => row.playwright.matches_server),
    fetch_body_errors: rows.filter(row => row.fetch.error).length,
    runtime_failure: runtime.failure, network: 'loopback-only',
    conclusion: fetchPreserves ? 'Fetch.getResponseBody preserves all tested server bytes before continueResponse'
      : 'Fetch.getResponseBody did not preserve every tested server body; inspect comparisons' });
  if (rows.some(row => row.fetch.error)) process.exitCode = 1;
} catch (error) {
  process.exitCode = 1;
  emit({ type: 'probe-error', name: error.name, message: error.message, stack: error.stack });
} finally {
  restore?.();
  if (runtime) await runtime.close();
  if (server?.listening) {
    server.closeAllConnections();
    await new Promise(resolve => server.close(resolve));
  }
  await rm(directory, { recursive: true, force: true });
  emit({ type: 'cleanup', browser_profile_removed: runtime ? !existsSync(runtime.profile) : null,
    certificate_directory_removed: !existsSync(directory), exit_code: process.exitCode ?? 0 });
}
